        }
      ]
    },
    {
      "claim": "The events in Ljuboten occurred in the context of a non‑international armed conflict, activating the provisions of article 8(c).",
      "reasoning": "A non‑international armed conflict exists when there is protracted armed violence between governmental forces and an organized armed group. The National Liberation Army (NLA) was an organized armed group that carried out a land‑mine attack killing eight soldiers, prompting a large‑scale police and army response involving hundreds of armed personnel, heavy weapons, and sustained combat operations. The intensity and organization of the hostilities satisfy the threshold for an internal armed conflict, thereby bringing article 8(c) into force, which criminalises the acts listed in paragraph (c).",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "In the case of an armed conflict not of an international character, serious violations of article 3 common to the four Geneva Conventions of 12 August 1949, namely, any of the following acts committed against persons taking no active part in the hostilities..."
        }
      ]
    },
    {
      "claim": "Johan Tarčulovski bears individual criminal responsibility for the war crimes committed in Ljuboten.",
      "reasoning": "Customary international law holds that individuals are criminally responsible for war crimes they commit (rule 151). Moreover, commanders and superiors are liable for crimes committed pursuant to their orders (rule 152). Tarčulovski, as the officer who commanded the police unit, ordered and was present during the attacks, beatings, and arson. Under article 33(1) of the Rome Statute, the defence of acting on superior orders does not relieve him of responsibility. Consequently, both customary command responsibility and the statutory provision establish his individual liability.",
      "citations": [
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 151,
          "quoted_text": "Individuals are criminally responsible for war crimes they commit."
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 152,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed pursuant to their orders."
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "33(1)",
          "quoted_text": "The fact that a crime within the jurisdiction of the Court has been committed by a person pursuant to an order of a Government or of a superior, whether military or civilian, shall not relieve that person of criminal responsibility unless:"
        }
      ]
    },
    {
      "claim": "The defence that Tarčulovski was merely executing a lawful police operation or acting under orders is unavailable because the conduct was not a proportionate defensive act.",
      "reasoning": "Article 31(1)(c) of the Rome Statute permits the use of force in self‑defence only when it is reasonable, necessary, and proportionate to an imminent unlawful attack. The operation involved pre‑emptive entry into the village, indiscriminate firing into houses, and the systematic burning of civilian dwellings—acts that far exceed any legitimate defensive purpose and are not proportionate to the alleged threat. Therefore, the self‑defence justification does not apply, and the accused cannot rely on it to escape liability.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "31(1)(c)",
          "quoted_text": "The person acts reasonably to defend himself or herself or another person or, in the case of war crimes, property which is essential for the survival of the person or another person or property which is essential for accomplishing a military mission, against an imminent and unlawful use of force in a manner proportionate to the degree of danger to the person or the other person or property protected."
        }
      ]
    }
  ]
